-- Curated Keep TX Red article for 2026-08-07.
WITH seed AS (
  SELECT
    '2026-08-07-presidio-border-wall-levee-ruling'::text AS slug,
    'Border'::text AS category,
    'Federal Judge Allows Border-Wall Construction Through Presidio Levee System to Proceed'::text AS title,
    'A federal judge denied Presidio’s request to halt a border-wall project through the Texas town’s levee system, allowing DHS construction plans to move forward for now.'::text AS dek,
    'Associated Press'::text AS source_name,
    'https://apnews.com/article/a1534ab0dd9d0c1215d574dcd2098250'::text AS source_url,
    '2026-08-07T12:14:00Z'::timestamptz AS published_at,
    24::int AS score,
    FALSE::boolean AS is_breaking,
    '{"updated":"2026-08-07","intro":["A federal judge has refused to stop the Department of Homeland Security from moving ahead with border-wall construction through the levee system in Presidio, a small West Texas community along the Rio Grande. The ruling is a legal setback for the city, which argued that the project could increase flood risk and should not proceed without additional engineering and regulatory review."],"sections":[{"heading":"What the judge decided","paragraphs":["U.S. District Judge Reggie B. Walton denied Presidio’s request for an order blocking construction while the lawsuit continues. The judge concluded that the city had not shown a sufficient likelihood of success on the merits to justify immediate injunctive relief. That means DHS can continue its plans unless a later court decision, appeal or administrative change alters the project.","The ruling does not end every legal question surrounding the wall. It addresses whether construction should be paused at this stage, not necessarily every claim the city has raised. Presidio can continue litigating, but the practical stakes increase when construction is allowed to advance because physical work can become harder to unwind."]},{"heading":"Why the levee is central to the dispute","paragraphs":["Presidio sits in a desert river environment where flood-control infrastructure is critical to homes, roads and public facilities. The city argues that placing border-wall structures through or alongside the levee system could change how the flood-control works function and potentially create new vulnerabilities. Officials have sought additional assurances about engineering and review.","DHS has broad authority under federal immigration and border-security law, including the ability in some circumstances to waive environmental and procedural requirements that would normally apply to major construction. That authority has repeatedly produced litigation from cities, landowners, tribes and environmental groups that argue local risks are not receiving adequate consideration."]},{"heading":"The federal border-wall push","paragraphs":["The Presidio project is part of a much larger federal effort to expand physical barriers along the U.S.-Mexico border. The Trump administration has committed tens of billions of dollars to construction and has said it wants to accelerate completion of additional barrier segments. Texas remains a central focus because of the state’s long international boundary and large stretches without continuous wall infrastructure.","Supporters argue that physical barriers slow illegal crossings, direct traffic toward areas where agents can respond and reduce the number of people who can move quickly into the interior. Opponents argue that walls can shift migration routes rather than stop them, create environmental damage and impose costs on communities that must live with the infrastructure."]},{"heading":"Why Presidio is different from a large border city","paragraphs":["Presidio has only a few thousand residents, so a federal construction project can have an outsized effect on local government capacity and community life. Unlike El Paso or the Rio Grande Valley’s larger cities, Presidio has fewer engineering, legal and financial resources to contest or adapt to a project of national significance.","The town’s location also makes flood-control concerns especially concrete. Residents are not debating the wall only as an abstract immigration symbol; they are asking how steel, roads and construction interact with infrastructure meant to protect the community from the Rio Grande. That local engineering question exists alongside the national political argument."]},{"heading":"What Texans should watch next","paragraphs":["One key issue is whether the Army Corps of Engineers or other technical agencies become more involved in reviewing modifications around the levee. Another is whether Presidio appeals the denial of an injunction. Even without a full stop, litigation can influence design details, mitigation commitments and the documentation DHS must provide.","Landowners elsewhere along the border will also watch the case because it may signal how courts treat requests to halt construction when DHS invokes broad waiver authority. The more courts defer to federal border powers, the harder it may be for local plaintiffs to stop projects before construction begins."]},{"heading":"The larger Texas implications","paragraphs":["Texas has spent years at the center of overlapping state and federal border-security efforts. State-funded barriers, federal wall construction, National Guard deployments and legal fights over immigration enforcement often occupy the same geography. Presidio’s case shows how those broad policies ultimately become local questions about drainage, roads, property and public safety.","For now, the federal government has the advantage in court and can keep the project moving. Presidio’s legal challenge may still shape what happens next, but the city did not win the immediate pause it sought. That makes engineering oversight and transparent communication especially important as construction approaches the community’s flood-control system.","The case also shows why border infrastructure disputes can become local engineering disputes as much as national political fights. In Washington, a wall segment may be discussed as one piece of immigration policy. In Presidio, the same project intersects with a levee system, flood risk, municipal responsibilities and the physical geography of a small border community. Those different scales can produce sharply different priorities even when everyone is talking about the same construction. As work proceeds, the practical questions—how the structure is built, how drainage is protected and how agencies coordinate—will matter to residents regardless of the broader political argument."]},{"heading":"Source attribution","paragraphs":["This article is an independent Keep TX Red rewrite based on reporting from Associated Press. The original report is linked below for verification."]}],"faq":[],"sources":[{"label":"Associated Press — original report","url":"https://apnews.com/article/a1534ab0dd9d0c1215d574dcd2098250"}],"keyTakeaways":["A federal judge denied Presidio’s request to halt a border-wall project through the Texas town’s levee system, allowing DHS construction plans to move forward for now."]}'::jsonb AS body_json
), prepared AS (
  SELECT seed.*,
    (SELECT string_agg(value, ' ') FROM jsonb_array_elements_text(
      jsonb_path_query_array(seed.body_json, '$.intro[*]') ||
      jsonb_path_query_array(seed.body_json, '$.sections[*].paragraphs[*]')
    )) AS body_text
  FROM seed
)
INSERT INTO public.daily_articles
  (slug, internal_url, is_ingested, category, title, dek, source_name, source_url,
   published_at, score, is_breaking, kind, body, body_json)
SELECT slug, '/news/' || slug, FALSE, category, title, dek, source_name, source_url,
       published_at, score, is_breaking, 'news', body_text, body_json
FROM prepared
ON CONFLICT (slug) DO UPDATE SET
  internal_url=EXCLUDED.internal_url, is_ingested=EXCLUDED.is_ingested,
  category=EXCLUDED.category, title=EXCLUDED.title, dek=EXCLUDED.dek,
  source_name=EXCLUDED.source_name, source_url=EXCLUDED.source_url,
  published_at=EXCLUDED.published_at, score=EXCLUDED.score,
  is_breaking=EXCLUDED.is_breaking, kind=EXCLUDED.kind,
  body=EXCLUDED.body, body_json=EXCLUDED.body_json;
